window.FS_DATA=window.FS_DATA||{};FS_DATA["pasdarka"]={"title":"Pasdarka","scores":{"zoti":{"title":"Zoti është bashkë me ne","pages":["img/nota/pm23.webp","img/nota/pm24.webp","img/nota/pm25.webp","img/nota/pm26.webp","img/nota/pm27.webp"]},"kerubim":{"title":"Me trumbeta kipre çdo Kerubim","pages":["img/nota/pm27.webp","img/nota/pm28.webp","img/nota/pm29.webp"]},"zonje":{"title":"Zonjë Hyjlindëse e Tërëshenjtë, ndërmjeto","pages":["img/nota/pm29.webp","img/nota/pm30.webp"]},"fuqi":{"title":"Zot i Madh i fuqive","pages":["img/nota/pm31.webp","img/nota/pm32.webp","img/nota/pm33.webp","img/nota/pm34.webp"]},"braktis":{"title":"Hyjlindëse, mos më braktis · Gjithë shpresën","pages":["img/nota/pm35.webp","img/nota/pm36.webp"]}},"sections":[{"title":"Shërbesat e Pasdarkës","items":[{"title":"Pasdarka e Vogël","ref":"Thuhet çdo mbrëmje pas darkës","priest":true,"blocks":[{"t":"role","who":"Prifti","x":"I bekuar është Perëndia ynë gjithnjë; tani e përherë e në jetë të jetëve.","pr":1},{"t":"role","x":"Në emër të Atit e Birit edhe Shpirtit të Shenjtë.","np":1,"who":"Lexuesi"},{"t":"role","who":"Lexuesi","x":"Amin"},{"t":"role","who":"Prifti / Lexuesi","x":"Lavdi më Ty, o Krisht Perëndi, shpresa jonë, lavdi më Ty."},{"t":"p","x":"O Mbret qiellor, Ngushëllimtar, Shpirti i së vërtetës, që ndodhesh kudo dhe i mbush të gjitha, thesari i të mirave dhe dhurues jete; eja dhe qëndro ndër ne dhe pastrona nga çdo njollë dhe shpëto, o i Mirë, shpirtrat tanë."},{"t":"role","who":"Lexuesi","x":"Amin."},{"t":"p","x":"Shenjt Perëndi, Shenjt i fuqishëm, Shenjt i pavdekshëm, mëshirona (3 herë)."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Trini e Tërëshenjtë, mëshirona; o Zot, fali mëkatet tona; o Zot i madh, ndjei paudhësitë tona; o i Shenjtë, vështro dhe shëro sëmundjet tona për emrin tënd."},{"t":"p","x":"Mëshiro, o Zot (3 herë)."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Ati ynë që je në qiejt, u shenjtëroftë emri yt, ardhtë mbretëria jote, u bëftë dëshira jote, si në qiell ashtu edhe mbi dhe. Bukën tonë të përditshme jepna neve sot; dhe falna fajet tona sikurse edhe ne ua falim fajtorëve tanë; dhe mos na shtjer në ngasje, po shpëtona nga i ligu."},{"t":"role","who":"Prifti","x":"Se jotja është mbretëria, dhe fuqia, dhe lavdia e Atit, e Birit dhe e Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve.","pr":1},{"t":"role","who":"Lexuesi","x":"Amin.","pr":1},{"t":"p","x":"Mëshiro, o Zot (12 herë)."},{"t":"p","x":"Ejani t'i falemi e t'i biem ndër këmbë Mbretit, Perëndisë tonë."},{"t":"p","x":"Ejani t'i falemi e t'i biem ndër këmbë Krishtit, Mbretit, Perëndisë tonë."},{"t":"p","x":"Ejani t'i falemi e t'i biem ndër këmbë vetë Krishtit, Mbretit e Perëndisë tonë."},{"t":"h","x":"Psalmi 50"},{"t":"p","x":"Përdëllemë, o Perëndi, sipas përdëllimit tënd të madh dhe sipas dhembshurive të tua të shumta shuaj e paudhësinë time. Lamë krejt prej paudhësisë sime dhe pastromë prej mëkatit tim. Se unë e njoh paudhësinë time dhe mëkati im është përpara meje kurdoherë. Te ti vetëm mëkatova dhe të keqen e bëra përpara teje, kështu që ti je i drejtë në fjalët e tua dhe i kthjellët në gjykimin tënd. Se ja tek u zura në paudhësi, dhe në mëkate më lindi nëna ime. Se ja tek deshe të vërtetën, të patreguarat dhe të fshehtat e urtësisë sate m'i tregove. Spërkatmë me hisop dhe do të pastrohem, lamë dhe do të bëhem më i bardhë se dëbora."},{"t":"p","x":"Bëmë të dëgjoj gëzim e ngazëllim dhe do të më gëzohen eshtrat e dobësuara. Ktheje fytyrën tënde nga mëkatet e mia dhe shuaji gjithë paudhësitë e mia: Krijo zemër të pastër tek unë, o Perëndi, dhe përtëri frymë të drejtë në thellësitë e zemrës sime. Mos më hidh larg prej fytyrës sate dhe mos e hiq prej meje Shpirtin tënd të Shenjtë. Jepma prapë ngazëllimin e shpëtimit tënd dhe forcomë me frymë sunduese. Do t'u mësoj të paligjve udhët e tua dhe të pabesët do të kthehen tek ti. Shpëtomë prej gjakrash, o Perëndi, Perëndia i shpëtimit tim, gjuha ime do të lavdërojë me gëzim drejtësinë tënde. O Zot, çel buzët e mia dhe goja ime do të lëçitë lavdinë tënde. Se po të kishe dashur therore do të kisha prurë, por ty s'të pëlqejnë therore me djegie të plotë. Therore ndaj Perëndisë është shpirti i dërrmuar; zemrën e dërrmuar dhe të përulur Perëndia nuk do ta përbuzë. Bëji të mirë, o Zot, Sionit sipas mirëdashjes sate dhe le të ndërtohen muret e Jerusalemit. Atëherë do të të pëlqejnë therore drejtësie, dhurata dhe therore me djegie të plotë. Atëherë do të sjellin viça mbi altarin tënd."},{"t":"h","x":"Psalmi 69"},{"t":"p","x":"O Perëndi, ndihmës sime vëri re, o Zot, shpejto të më ndihmosh. U marrofshin e u turpërofshin ata që shpirtin tim kërkojnë; Shpatullat kthefshin me turp dhe u mbulofshin ata që të keqen time duan. Mbrapsht u kthefshin menjëherë të turpëruar ata që më thonë: Të lumtë, të lumtë! U ngazëllofshin e u dëfrefshin në ty të gjithë ata që të kërkojnë, o Perëndi, dhe ata që duan shpëtim prej teje, thënshin përgjithnjë: U madhëroftë Zoti! Dhe unë jam i varfër e nevojtar; o Perëndi, ndihmomë. Ti je ndihmësi im dhe çlirimtari im, o Zot; mos u vono."},{"t":"h","x":"Psalmi 142"},{"t":"p","x":"O Zot, dëgjo faljen time, vëri veshin lutjes sime sipas së vërtetës sate, dëgjomë sipas drejtësisë sate. Dhe mos hyr në gjyq me shërbëtorin tënd, se asnjë i gjallë nuk do të dalë i drejtë përpara teje. Se armiku ma ndoqi shpirtin dhe ma rrëzoi jetën përdhe. Më vuri në vende të errëta, si të vdekurit prej kohe, shpirti m'u trishtua dhe zemra m'u trondit."},{"t":"p","x":"Kujtova ditët e lashta, mendova gjithë veprat e tua, sillja ndër mend punët e duarve të tua. I shtriva duart drejt teje; shpirti im ka etje për ty si toka e thatë. Dëgjomë shpejt, o Zot, m'u zu fryma, mos e kthe mënjanë fytyrën tënde prej meje, që të mos bëhem si ata që zbritën në varr. Bëmë që të dëgjoj përdëllimin tënd në mëngjes se tek ty shpresova. Tregomë, o Zot, udhën ku duhet të eci, se tek ty e kam varur shpirtin. Shpëtomë prej armiqve të mi, o Zot, se tek ti kërkova strehë. Mësomë të bëj vullnetin tënd se ti je Perëndia im. Fryma jote e mirë do të më udhëheqë në vend të drejtë, për emrin tënd, o Zot, gjallëromë. Sipas drejtësisë sate nxirr shpirtin tim nga trishtimi, dhe sipas mëshirës sate shfarosi armiqtë e mi, dhe shkatërroi të gjithë ata që hidhërojnë shpirtin tim se unë jam shërbëtori yt."},{"t":"h","x":"Dhoksologjia"},{"t":"p","x":"Lavdi Perëndisë në më të larta dhe mbi dhenë paqe dhe mbi njerëzit mirëdashje."},{"t":"p","x":"Të himnojmë, të bekojmë, të falemi, të lavdërojmë, ty të falënderojmë për lavdinë tënde të madhe. Zot Mbret, Perëndi qiellor, At i tërëfuqishëm. Zot Bir i vetëmlindur Jisu Krisht, edhe Shpirti i Shenjtë. Zot Perëndi, qengj i Perëndisë, Bir i Atit që ngre mëkatin e botës; mëshirona, ti që ngre mëkatet e botës. Prano lutjen tonë, ti që rri në të djathtë të Atit, edhe mëshirona. Se ti je shenjt i vetëm, ti je Zot i vetëm, Jisu Krisht, për lavdi të Perëndisë Atit. Amin. Për çdo mbrëmje do të të bekoj, dhe do të lavdëroj emrin tënd për jetë e në jetë të jetës. O Zot, u bëre streha jonë brez pas brezi, unë thashë: a Zot mëshiromë, shëro shpirtin tim se fajtova tek ti. O Zot, tek ti gjeta strehë, mësomë të bëj dëshirën tënde se ti je Perëndia im. Se pranë teje është burimi i jetës; me dritën tënde do të shohim dritë. Zgjate përdëllimin tënd mbi ata që të njohin. Bëna të denjë, o Zot, që të ruhemi këtë natë pa ndonjë mëkat. I bekuar je, o Zot, Perëndi i Etërve tanë, dhe emri yt është i himnuar dhe i lavdëruar në jetët. Amin."},{"t":"p","x":"Le të jetë, o Zot, përdëllimi yt mbi ne, sikurse kemi shpresuar tek ti. I bekuar je, o Zot, mësomë porositë e tua. I bekuar je, o Zot, bëmë të mençëm në porositë e tua. I bekuar je, o i Shenjtë, ndriçomë me porositë e tua. O Zot, mëshira jote është për jetë, mos i hiq sytë nga veprat e duarve të tua. Ty të ka hije lavdërimi, ty të ka hije himni, ty të ka hije lavdia, Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"h","x":"Simboli i Besimit"},{"t":"p","x":"Besoj në një Perëndi, Atë të tërëfuqishëm, krijues të qiellit edhe të dheut dhe të gjithë të dukurave dhe të padukurave. Dhe në një Zot, Jisu Krishtin, Birin e Perëndisë, të vetëmlindurin, që lindi prej Atit përpara gjithë shekujve. Dritë prej drite, Perëndi të vërtetë prej Perëndie të vërtetë, të lindur, jo të bërë, që ka të qenët një me Atin, me anën e të cilit u bënë të gjitha. Që për ne njerëzit dhe për shpëtimin tonë, zbriti prej qiejve dhe u trupëzua prej Shpirtit të Shenjtë dhe Virgjëreshës Mari dhe u bë njeri."},{"t":"p","x":"Dhe u kryqëzua për ne në kohën e Pontit Pilat, dhe pësoi e u varros. Dhe u ngjall të tretën ditë sipas shkrimeve. Dhe u ngjit në qiejt dhe rri në të djathtë të Atit. Dhe do të vijë përsëri me lavdi të gjykojë të gjallët dhe të vdekurit, mbretëria e të cilit nuk do të ketë mbarim. Dhe në Shpirtin e Shenjtë, Zot, Jetëbërës, që buron prej Atit, që adhurohet e lavdërohet bashkë me Atin e me Birin, që foli me anën e profetëve. Në një Kishë të shenjtë, katholike dhe apostolike. Pohoj një pagëzim për ndjesën e mëkateve. Pres ngjalljen e të vdekurve. Dhe jetën e ardhshme të amëshuar. Amin."},{"t":"p","x":"Të meriton me të vërtetë të të lumturojmë, Ty Hyjlindësen, gjithmonë të lumturën dhe të përmbikulluarën dhe Mëmën e Perëndisë tonë. Më të nderuarën se Keruvimet dhe më të lavdëruarën pa krahasim se Serafimet, që pa u cënuar linde Fjalën Perëndi, me të vërtetë Hyjlindësen, Ty të madhërojmë."},{"t":"p","x":"Shenjt Perëndi, Shenjt i fuqishëm, Shenjt i pavdekshëm, mëshirona (3 herë)."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Trini e Tërëshenjtë, mëshirona; o Zot, fali mëkatet tona; o Zot i madh, ndjei paudhësitë tona; o i Shenjtë, vështro dhe shëro sëmundjet tona për emrin tënd."},{"t":"p","x":"Mëshiro, o Zot (3 herë)."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Ati ynë që je në qiejt, u shenjtëroftë emri yt, ardhtë mbretëria jote, u bëftë dëshira jote, si në qiell ashtu edhe mbi dhe. Bukën tonë të përditshme jepna neve sot; dhe falna fajet tona sikurse edhe ne ua falim fajtorëve tanë; dhe mos na shtjer në ngasje, po shpëtona nga i ligu."},{"t":"role","who":"Prifti","x":"Se jotja është mbretëria, dhe fuqia, dhe lavdia e Atit, e Birit dhe e Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve.","pr":1},{"t":"role","who":"Lexuesi","x":"Amin.","pr":1},{"t":"rubric","x":"Pastaj thuhet tropari i shenjtit të ditës, ose troparet e mëposhtme:"},{"t":"p","x":"O Perëndi i Etërve tanë, Ti që je gjithmonë me ne, sipas butësisë sate, mos largo mëshirën tënde, por me lutjet e tyre drejto me paqe jetën tonë."},{"t":"p","x":"Kisha jote e stolisur si me porfir dhe vis, me gjakun e martirëve të tu në gjithë botën, të thërret me anën e tyre, o Krisht Perëndi: Dërgoi dhembshuritë e tua popullit tënd, dhuroi paqe shtetit tënd dhe shpirtrave tanë përdëllimin e madh."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë."},{"t":"p","x":"Bashkë me shenjtorët prehi, o Krisht, shpirtrat e shërbëtorëve të tu, atje ku nuk ka as dhembje, as hidhërim, as psherëtimë, por jetë të pambaruar."},{"t":"p","x":"Tani e përherë e në jetë të jetëve. Amin"},{"t":"p","x":"O Zot, me ndërmjetimet e gjithë shenjtorëve dhe të Hyjlindëses, jepna paqen tënde dhe mëshirona si i vetëm zemërdhembshur."},{"t":"p","x":"Mëshiro, o Zot (40 herë)."},{"t":"p","x":"O Krisht Perëndi, që adhurohesh e lavdërohesh në çdo kohë e në çdo orë në qiell e mbi dhe, Ti që je zemërgjerë, i shumëmëshirshëm i shumëdhembshur, që i do të drejtët dhe i përdëllen mëkatarët, që i fton të gjithë për shpëtim me premtimin e të mirave të pritme. Ti o Zot, prano lutjet tona në këtë orë dhe drejto jetën tonë tek porositë e tua. Shenjtërona shpirtrat, pastrona trupat, ndreqna mendimet pastrona mendjet dhe shpëtona prej çdo hidhërimi, të këqijash dhe vuajtjesh; mbrona me engjëjt e tu të shenjtë që, duke u ruajtur dhe duke u udhëhequr prej ushtrisë së tyre, të arrijmë në bashkimin e besimit dhe në njohjen e lavdisë Sate të paafrueshme, se i bekuar je në jetë të jetëve. Amin."},{"t":"p","x":"Mëshiro, o Zot (3herë)."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Më të nderuarën se Keruvimet dhe më të lavdëruarën pa krahasim se Serafimet, që pa u cënuar linde Fjalën Perëndi, me të vërtetë Hyjlindësen, ty të madhërojmë."},{"t":"p","x":"Beko, o Atë, në emër të Zotit.","pr":1},{"t":"role","who":"Prifti","x":"Perëndia na përdëlleftë dhe na bekoftë, shfaqtë fytyrën e Tij mbi ne dhe na mëshiroftë.","pr":1},{"t":"role","x":"Me uratat e Etërve tanë të shenjtë, o Zot Jisu Krisht Perëndi, mëshirona dhe shpëtona.","np":1,"who":"Lexuesi"},{"t":"role","who":"Lexuesi","x":"Mëshiro, o Zot (12 herë)."},{"t":"p","x":"Dhe shpëtona, o Virgjëreshë e Tërëshenjtë."},{"t":"h","x":"Lutje Hyjlindëses së Tërëshenjtë"},{"t":"rubric","x":"(Nga Pavli, murg i Manastirit të Evergjetit)"},{"t":"p","x":"E papikëluar, e papërlyer, e pacënuar, e panjollshme, Virgjëreshë e pastër, Zonjë Nuse e Perëndisë, që bashkove Fjalën Perëndi me njerëzit me lindjen tënde të çuditshme dhe mbështete natyrën e hedhur të gjinisë sonë me qiellorët; e vetmja shpresë e të dëshpëruarve dhe ndihma e të luftuarve; përkrahja e gatshme e atyre që rendin tek ti dhe strehë e gjithë të krishterëve; mos të ardhtë ndot nga unë mëkatari, i mallkuari, që prisha tërë veten time me mendime, fjalë dhe vepra të turpshme dhe që u bëra rob me dashje nga plogështia mendore e dëfrimeve të jetës; por si Nënë e Perëndisë njeridashës, me dashamirësi le të të vijë keq për mua mëkatarin dhe plangprishësin, dhe prit lutjen që të blatohet prej buzësh të ndotura; dhe lutju Birit tënd dhe mbretit e Zotit tonë, duke përdorur guximin tënd prej nëne që të ma hapë dhe mua zemrën njeridashëse të mirësisë së tij; dhe, duke mos vënë re fjalët e mia të panumërta, të më kthejë në pendim dhe të më bëjë punëtor të sprovuar të porosive te tij. Dhe ji pranë meje gjithnjë, si mëshirëplotë, hirplotë dhe mirëdashëse; në këtë jetë mbrojtëse dhe ndihmëse e nxehtë, duke thyer sulmet e kundërshtarëve dhe duke më udhëhequr drejt shpëtimit; dhe në kohë të ikjes sime, duke u kujdesur për shpirtin tim të mjerë dhe duke dëbuar larg faqet e errëta të demonëve të ligj; dhe në ditën e frikshme të gjyqit shpëtomë nga Ferri i amëshuar dhe tregomë trashëgimtar të lavdisë së patregueshme të Birit tënd dhe Perëndisë tonë; të Cilin e paça, o Zonja ime, Hyjlindëse e përmbishenjtë, me ndërmjetimin dhe përkrahjen tënde me hirin dhe njeridashjen e Birit tënd të vetëmlindur, Zotit dhe Perëndisë dhe Shpëtimtarit tonë Jisu Krishtit; të Cilit i përket çdo lavdi, nder e adhurim, bashkë me Atin e tij të pafillim dhe Shpirtin e tij të Tërëshenjtë, të mirë e jetëbërës, tani e përherë e në jetë të jetëve. Amin."},{"t":"h","x":"Lutje Zotit tonë Jisu Krisht"},{"t":"rubric","x":"(Nga Andiohu, murg i Pandhektit)"},{"t":"p","x":"Dhe jepna, o Zot, neve që shkojmë për gjumë, prehje trupi dhe shpirti; dhe ruajna nga gjumi i errët i mëkatit dhe prej çdo epshi të errët të natës. Pusho hovet e pasioneve, shuaj shigjetat e zjarrta të të ligut që lëvizin kundër nesh dinakërisht; thyej kryengritjet e trupit tonë dhe vër në gjumë çdo mendim tokësor e lëndor. Dhe dhurona, o Perëndi, mendje vigjëluese, mendim të urtë, zemër esëll, gjumë të lehtë dhe pa ndonjë fantazi satanike. Dhe zgjona në kohë të faljes, të mbështetur në porositë e tua e duke pasur në veten tonë kujtimin e pathyer të gjykimeve të tua. Falna lavdërimin tënd tërë natën, që të himnojmë, të bekojmë e të lavdëroj më emrin tënd të gjithënderuar e madhështor, të Atit e të Birit dhe të Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"E përmbi lavdëruar, gjithmonëvirgjër, e bekuar Hyjlindëse, dërgoja faljen tonë Birit tënd dhe Perëndisë tonë dhe lypi që të shpëtojë me anën tënde shpirtrat tanë."},{"t":"p","x":"O At, shpresa ime. O Bir përikja ime. Shpirti i Shenjtë, mburoja ime. Trini e Shenjtë, lavdi më Ty."},{"t":"p","x":"Gjithë shpresën time e vë tek ti, o Nënë e Perëndisë; ruajmë nën mbrojtjen tënde."},{"t":"p","x":"Me ty gëzohet, o Hirplotë, gjithë krijesa tërësia e engjëjve, dhe gjinia e njerëzve: o tempull i shenjtëruar dhe parajsë shpirtërore, mburrja e virgjërisë; prej së cilës u trupëzua dhe u bë djalë Perëndia ynë që është para jetëve. Se mitrën tënde e bëri fron dhe barkun tënd më të gjerë se qiejt. Me ty gëzohet, o Hirplotë, gjithë krijesa; lavdi më ty."},{"t":"h","x":"Lutje Engjëllit ruajtës"},{"t":"p","x":"O Engjëll i shenjtë, mbrojtës i shpirtit tim të mjerë dhe i jetës sime të vuajtur, mos më lër, mua mëkatarin, as mos u largo prej meje për ngathtësinë time, mos i lësho vend djallit të lig për të pushtuar e sunduar trupin tim të vdekshëm, mbamë nga dora ime e mjerë dhe e mpirë dhe drejtomë tek udha e shpëtimit. Po, o Engjëll i shpirtit dhe i trupit tim të mjerë, ndjemë për gjithçka me të cilat të kam hidhëruar gjatë gjithë ditëve të jetës sime, si dhe për ndonjë faj të bërë ditën e sotme, mbromë edhe këtë natë dhe ruajmë nga çdo ndikim i armikut, që të mos e zemëroj Perëndinë me ndonjë faj dhe ndërmjeto tek Zoti për mua të më forcojë me frikën e tij dhe të më tregojë shërbëtor të denjë të mirësisë së tij. Amin."},{"t":"p","x":"Përlufteshës gjenerale këngët mundëse, Si përhirim që e shpëtove prej tmerreve, Qyteti yt të përshkruan, o Virgjëreshë. Po sikundër ke fuqi të paluftueshme, Prej çfarëdo rreziku shpëtomë; Se po të thërres: Gëzohu, o Nuse e panusëruar!"},{"t":"p","x":"Gëzohu, o hirplotë Hyjlindëse Virgjëreshë Mari, Zoti është me ty. E bekuar je ti ndër gratë dhe e bekuar është pema e barkut tënd, se linde Shpëtimtarin e shpirtrave tanë."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin.","pr":1},{"t":"p","x":"Mëshiro, o Zot (3 herë).","pr":1},{"t":"p","x":"Beko, o Atë i shenjtë.","pr":1},{"t":"role","who":"Prifti","x":"Krishti Perëndia ynë i vërtetë me ndërmjetimet e Nënës së Tij të pacënuar dhe krejt të papërlyer, me fuqinë e Kryqit të nderuar dhe jetëbërës; me mbrojtjet e Fuqive të nderuara qiellore, të patrup; me lutjet e Profetit të nderuar e të lavdëruar, Pararendës e Pagëzor Joan; të apostujve të shenjtë, të lavdëruar e të dëgjuar; të Martirëve të shenjtë, të lavdëruar dhe mundës të shkëlqyer; të Etërve tanë oshënarë dhe hyjprurës; të Hyjprindërve të shenjtë e të drejtë Joakim dhe Ana, të shenjtit (të ditës) që lusim sot dhe të gjithë shenjtorëve, na mëshiroftë dhe na shpëtoftë si Perëndi i mirë dhe njeridashës.","pr":1},{"t":"role","who":"Lexuesi","x":"Amin.","pr":1},{"t":"rubric","x":"Pastaj prifti thotë këto urata si më poshtë dhe populli, përgjigjet çdo herë: Mëshiro, o Zot.","pr":1},{"t":"role","who":"Prifti","x":"Le të lutemi për paqen e botës. Për të krishterët shpresëtarë dhe orthodhoksë. Për Kryepiskopin tonë (aksh) dhe gjithë vëllazërinë tonë më Krishtin. Për etërit dhe vëllezërit tanë që mungojnë. Për ata që na urrejnë dhe për ata që na duan. Për ata që na ndihmojnë dhe na shërbejnë. Për ata që na porositën ne të padenjët të lutemi për ta. Për çlirimin e robërve. Për ata që udhëtojnë mirë në det dhe në ajër. Për ata që dergjen në sëmundje. Le te lutemi dhe për pjellorinë e pemëve të dheut. Dhe për gjithë etërit dhe vëllezërit tanë orthodhoksë që u prehën më parë, këtu e kudo. Le të themi dhe për veten tonë: Mëshiro, o Zot. Mëshiro, o Zot. Mëshiro, o Zot.","pr":1},{"t":"h","x":"O bukuri me nam · Ting. III"},{"t":"chant","x":"O bukuri me nam,* o virgjëri pa cen,* o drit’ e diellit,* o hën’ e qiellit,* shën Gabrieli kur të pa,* çuditej dhe të thërriste:* Si të të lavdëroj,* o Mari, o Hyjlindëse?* Ç’ këngë të këndoj për ty?* Nuk e di dhe kërkoj më kot.* Pra, them sikundër jam porositur:* Gëzohu, Virgjëreshë hirplote.*","tone":"Ting. III – Tin oreotita"},{"t":"role","who":"Prifti","x":"Me uratat e Etërve tanë të shenjtë, o Zot Jisu Krisht, mëshirona dhe shpëtona.","pr":1},{"t":"role","who":"Lexuesi","x":"Amin.","pr":1},{"t":"role","who":"Lexuesi","x":"Me uratat e Etërve tanë të shenjtë, o Zot Jisu Krisht, Perëndia ynë, mëshirona dhe shpëtona. Amin.","np":1}]},{"title":"Pasdarka e Madhe","ref":"Thuhet gjatë Kreshmëve të Mëdha","priest":true,"blocks":[{"t":"rubric","x":"Thuhet të Hënën, të Martën, të Mërkurën dhe të Enjten gjatë Kreshmëve, përveç të Mërkurën e Javës së Pestë, pas Himnit Akathist, bëhet Agripni: Kanon i Madh për të Enjten së bashku me Mëngjesoren dhe Orën e Parë. Të Enjten në mëngjes Ungjilli, Orët, Tipika e Kreshmëve, Mbrëmësore dhe Liturgji të Parashenjtëruarash."},{"t":"rubric","x":"Të Hënën dhe të Martën e Javës së Madhe dhe të Shenjtë."},{"t":"role","who":"Prifti","x":"I bekuar është Perëndia ynë, gjithnjë, tani e përherë e në jetë të jetëve.","pr":1},{"t":"role","who":"Lexuesi","x":"Amin.","pr":1},{"t":"role","who":"Lexuesi","x":"Në emër të Atit e të Birit dhe të Shpirtit të Shenjtë. Amin.","np":1},{"t":"p","x":"Lavdi më Ty, o Krisht Perëndia ynë, lavdi më Ty."},{"t":"p","x":"O Mbret qiellor, Ngushëllimtar, Shpirt i së vërtetës, që ndodhesh kudo dhe i mbush të gjitha, thesari i të mirave dhe dhurues jete; eja dhe qëndro ndër ne dhe pastrona nga çdo njollë dhe shpëto, o i Mirë, shpirtrat tanë."},{"t":"h","x":"Trishenjti"},{"t":"p","x":"Shenjt Perëndi, Shenjt i fuqishëm, Shenjt i pavdekshëm, mëshirona. (3 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Trini e Tërëshenjtë, mëshirona; o Zot, falna mëkatet tona; o Zot i madh, ndjei paudhësitë tona; o i Shenjtë, vështro dhe shëro sëmundjet tona, për emrin tënd."},{"t":"p","x":"Mëshiro, o Zot. (3 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Ati ynë që je në qiejt, u shenjtëroftë emri yt, ardhtë mbretëria jote, u bëftë dëshira jote si në qiell ashtu edhe mbi dhe. Bukën tonë të përditëshme jepna neve sot; dhe falna fajet tona, sikurse edhe ne ua falim fajtorëve tanë; dhe mos na shtjer në ngasje, po shpëtona nga i ligu."},{"t":"p","x":"Ejani t’i falemi e t’i biem ndër këmbë Perëndisë, Mbretit tonë."},{"t":"p","x":"Ejani t’i falemi e t’i biem ndër këmbë Krishtit, Perëndisë, Mbretit tonë."},{"t":"p","x":"Ejani t’i falemi e t’i biem ndër këmbë vetë Krishtit, Perëndisë dhe Mbretit tonë."},{"t":"rubric","x":"Dhe menjëherë, nëse është java e parë e Kreshmëve të mëdha, fillojmë me:"},{"t":"h","x":"Psalmi 69"},{"t":"p","x":"O Perëndi, ndihmës sime vëri re; o Zot, nxito të më ndihmosh."},{"t":"p","x":"U çnderofshin dhe u turpërofshin ata që kërkojnë shpirtin tim; u kthefshin prapa dhe u turpërofshin ata që duan të këqija kundër meje."},{"t":"p","x":"U kthefshin menjëherë prapa të turpëruar ata që më thonë: Sa mirë, sa mirë!"},{"t":"p","x":"U gëzofshin dhe u dëfrefshin në ty të gjithë ata që të kërkojnë, o Perëndi, edhe ata që duan shpëtimin tënd thënçin përgjithnjë: Zoti qoftë i madhëruar!"},{"t":"p","x":"Po unë jam i varfër dhe nevojtar, o Perëndi, ndihmomë."},{"t":"p","x":"Ti je ndihmësi dhe shpëtimtari im; o Zot, eja shpejt, mos u vono."},{"t":"p","x":"Nëse jo, fillojmë kështu:"},{"t":"h","x":"Psalmi 4"},{"t":"p","x":"Kur të thirra, më dëgjove, o Perëndi i drejtësisë sime, në hidhërim më ngushëllove; ki dhembshuri për mua dhe dëgjoje lutjen time."},{"t":"p","x":"O bij njerëzish, deri kur do të jeni të rëndë në zemër?"},{"t":"p","x":"Përse e doni kotësinë dhe kërkoni gënjeshtrën?"},{"t":"p","x":"Dhe ta dini se Zoti e madhështoi oshënarin e tij."},{"t":"p","x":"Zoti do të më dëgjojë kur do t'i thërres."},{"t":"p","x":"Zemërohuni dhe mos mëkatoni; për ato që thoni në zemrat tuaja, në shtretërit tuaj pendohuni."},{"t":"p","x":"Therore drejtësie flijoni dhe shpresoni në Zotin. Shumë thonë: Kush do të na i tregojë të mirat?"},{"t":"p","x":"U shënua mbi ne drita e fytyrës sate, o Zot."},{"t":"p","x":"I dhe ngazëllim zemrës sime; nga fryti i grurit, verës dhe vajit të tyre u ngopën."},{"t":"p","x":"Prandaj në paqe do të bie në gjumë dhe do të fle, se ti, o Zot, edhe pse jam i vetmuar, më bëre të jetoj me shpresë."},{"t":"h","x":"Psalmi 6"},{"t":"p","x":"O Zot, mos më qorto në inatin tënd, as mos më mundo në zemërimin tënd."},{"t":"p","x":"Mëshiromë, o Zot, se jam i sëmurë; shëromë, o Zot, se eshtrat e mia u tronditën, edhe shpirti im u trazua fort; dhe ti, o Zot, deri kur do të jesh i zemëruar me mua?"},{"t":"p","x":"Kthehu, o Zot, çliroje shpirtin tim, shpëtomë për hir të mëshirës sate."},{"t":"p","x":"Se në vdekje s'ka kush të të kujtojë, dhe në Hadh kush do të të lavdërojë?"},{"t":"p","x":"U këputa nga rënkimet e mia, çdo natë e laj shtratin tim, me lotët e mi e lag shtrojën time."},{"t":"p","x":"Syri m'u drodh nga zemërimi, u plaka për shkak të gjithë armiqve të mi."},{"t":"p","x":"Largohuni prej meje gjithë ju që punoni paudhësinë; se Zoti e dëgjoi zërin e së qarës sime."},{"t":"p","x":"Zoti e dëgjoi përgjëratën time, Zoti e priti lutjen time."},{"t":"p","x":"U turpërofshin dhe u turbullofshin fort gjithë armiqtë e mi, u kthefshin pas dhe menjëherë fort u turpërofshin."},{"t":"h","x":"Psalmi 12"},{"t":"p","x":"Deri kur, o Zot, do të më harrosh gjer në fund?"},{"t":"p","x":"Deri kur do ta kthesh mënjanë fytyrën tënde prej meje?"},{"t":"p","x":"Deri kur do të marr vendime në shpirtin tim, dhimbje në zemrën time ditë e natë?"},{"t":"p","x":"Deri kur do të lartësohet armiku im mbi mua?"},{"t":"p","x":"Vështromë, dëgjomë, o Zot, Perëndia im, ndriçoji sytë e mi se mos fle gjumin e vdekjes."},{"t":"p","x":"Se mos thotë armiku im: Dola më i fortë se ai."},{"t":"p","x":"Ata që më shtrëngojnë, do të ngazëllehen nëse unë lëkundem."},{"t":"p","x":"Por unë shpresova në mëshirën tënde."},{"t":"p","x":"Zemra ime do të ngazëllehet për shpëtimin tënd; do t'i këndoj Zotit që më bëri të mira dhe do t'i psal emrit të Zotit, të të Lartit."},{"t":"p","x":"Dhe përsëri:"},{"t":"p","x":"Vështomë, dëgjomë, o Zot, Perëndia im, ndriçoji sytë e mi se mos fle gjumin e vdekjes. Se mos thotë armiku im: Dola më i fortë se ai. Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Aliluia, Aliluia, Aliluia. Lavdi më Ty, o Perëndi (3 herë)."},{"t":"p","x":"Mëshiro, o Zot. (tri herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"h","x":"Psalmi 24"},{"t":"p","x":"Tek ti, o Zot, e ngrita shpirtin tim."},{"t":"p","x":"O Perëndia im, tek ti shpresova; mos u turpërofsha në jetë të jetëve, as mos u tallshin me mua armiqtë e mi."},{"t":"p","x":"Prandaj dhe të gjithë ata që shpresojnë tek ti, nuk do të turpërohen; u turpërofshin ata që punojnë më kot paudhësinë."},{"t":"p","x":"Tregomë udhët e tua, o Zot, edhe mësomë shtigjet e tua."},{"t":"p","x":"Udhëhiqmë në të vërtetën tënde, edhe mësomë, se ti je Perëndia, shpëtimtari im, dhe tek ti shpresova gjithë ditën."},{"t":"p","x":"Kujto, o Zot, dhembshuritë e tua edhe mëshirat e tua, se janë prej jetësh."},{"t":"p","x":"Mos i kujto mëkatet e rinisë sime dhe të paditurisë sime; sipas përdëllimit tënd, kujtomë ti, o Zot, për hir të mirësisë sate."},{"t":"p","x":"Zoti është i mirë dhe i drejtë, prandaj do t'u vërë ligje në udhë atyre që mëkatojnë."},{"t":"p","x":"Do t'i udhëheqë të butët në gjykim, do t'ua mësojë të butëve udhët e tij."},{"t":"p","x":"Gjithë udhët e Zotit janë përdëllim dhe e vërtetë për ata që kërkojnë dhiatën e tij dhe dëshmitë e tij."},{"t":"p","x":"Për hir të emrit tënd, o Zot, ndjeje mëkatin tim, sepse është i shumtë."},{"t":"p","x":"Cili është ai njeri që e ka frikë Zotin?"},{"t":"p","x":"Atij do t'ia japë ligjin në udhën që i pëlqeu."},{"t":"p","x":"Shpirti i tij do të banojë në të mira, edhe fara e tij do të trashëgojë dheun."},{"t":"p","x":"Zoti është mbështetje e fortë për ata që e kanë frikë, edhe dhiata e tij do t'i bëjë të njohur ata."},{"t":"p","x":"Sytë e mi janë kurdoherë te Zoti, se ai do t'i çlirojë këmbët e mia nga kurthi."},{"t":"p","x":"Shtjer syrin tënd mbi mua edhe përdëllemë, se unë jam i vetëm dhe i varfër."},{"t":"p","x":"Hidhërimet e zemrës sime u shumuan, nxirrmë prej shtrëngimeve të mia."},{"t":"p","x":"Shiko përulësinë time dhe mundimin tim, edhe falmi gjithë mëkatet e mia."},{"t":"p","x":"Shiko armiqtë e mi, se u shumuan, edhe më urrejnë, edhe më mbajnë mëri me të padrejtë."},{"t":"p","x":"Ruaje shpirtin tim dhe shpëtomë; mos u turpërofsha, se shpresova tek ti."},{"t":"p","x":"Njerëz të pa të keq dhe të drejtë më ndoqën pas, se tek ti shpresova, o Zot."},{"t":"p","x":"Çliroje Izraelin, o Perëndi, prej gjithë shtrëngimeve të tij."},{"t":"h","x":"Psalmi 30"},{"t":"p","x":"O Zot, tek ti shpresova, mos u turpërofsha përjetë, shpëtomë në drejtësinë tënde dhe çliromë."},{"t":"p","x":"Ule veshin tënd tek unë, nxito të më çlirosh, bëhu për mua Perëndi mbrojtës dhe strehë, që të më shpëtosh."},{"t":"p","x":"Sepse ti je mbrojtja ime dhe streha ime, për hir të emrit tënd do të më udhëheqësh dhe do të më ushqesh."},{"t":"p","x":"Do të më nxjerrësh prej këtij kurthi që ma fshehën, se ti je mbrojtësi im, o Zot."},{"t":"p","x":"Në duart e tua do ta jap frymën time; ti më shpëtove, o Zot, Perëndia i së vërtetës. Urreve ata që ruajnë kotësitë pa dobi."},{"t":"p","x":"Po unë shpresova te Zoti."},{"t":"p","x":"Do të gëzohem dhe do të ngazëllohem për përdëllimin tënd, sepse hodhe sytë mbi përulësinë time; e shpëtove prej rreziqeve shpirtin tim."},{"t":"p","x":"Edhe nuk më le në duart e armiqve; i vure këmbët e mia në vend të sigurt."},{"t":"p","x":"Përdëllemë, o Zot, sepse po hidhërohem; syri im u trondit prej zemërimit, edhe shpirti dhe barku im."},{"t":"p","x":"Sepse jeta ime u fik prej dhimbjes, edhe vitet e mia prej psherëtimave; fuqia ime u dobësua prej varfërisë, edhe eshtrat e mia u tronditën."},{"t":"p","x":"U bëra turp para gjithë armiqve të mi, edhe më shumë para fqinjëve të mi, edhe frikë për të njohurit e mi; ata që më shihnin, më largoheshin."},{"t":"p","x":"U harrova si një i vdekur prej vitesh, u bëra si enë e humbur."},{"t":"p","x":"Sepse dëgjova shpifje nga shumë njerëz që banonin rreth meje; kur ata u mblodhën kundër meje, vendosën që të më merrnin shpirtin."},{"t":"p","x":"Por unë, tek ti shpresova, o Zot, dhe thashë: Ti je Perëndia im."},{"t":"p","x":"Në duart e tua janë shortet e mia; çliromë prej dorës së armiqve të mi dhe prej atyre që më përndjekin."},{"t":"p","x":"Shfaqe fytyrën tënde mbi shërbëtorin tënd, shpëtomë në mëshirën tënde."},{"t":"p","x":"Mos u turpërofsha, o Zot, sepse ty të thirra; u turpërofshin të pabesët dhe rënçin në hadh."},{"t":"p","x":"U bëfshin memece buzët gënjeshtare, që me kryelartësi dhe poshtërim flasin paudhësi kundër të drejtit."},{"t":"p","x":"Sa të mëdha janë mirësitë e tua, o Zot, që i ruajte për ata që të kanë frikë, dhe i bëre për ata që shpresojnë tek ti, përpara bijve të njerëzve."},{"t":"p","x":"Do t'i fshehësh ata nga turbullimi i njerëzve në strehën e fshehtë të fytyrës sate; do t'i mbulosh ata në tendë nga kundërshtitë e gjuhëve."},{"t":"p","x":"I bekuar qoftë Zoti, se e shfaqi në mënyrë të mrekullueshme mëshirën e tij si në një qytet të mbrojtur."},{"t":"p","x":"Por unë thashë në habinë time: u hodha larg syve të tu, prandaj e dëgjove zërin e lutjes sime, kur thirra tek ti."},{"t":"p","x":"Duajeni Zotin, gjithë oshënarët e tij, se Zoti kërkon të vërtetën, edhe ua shpaguan me tepri kryelartëve."},{"t":"p","x":"Bëhuni burra dhe le të forcohet zemra juaj, gjithë ju që shpresoni te Zoti."},{"t":"h","x":"Psalmi 90"},{"t":"p","x":"Ai që banon në ndihmën e të Lartit, nën mbrojtjen e Perëndisë së qiellit do të gjejë strehë."},{"t":"p","x":"Do t'i thotë Zotit: Ti je mbështetja ime dhe streha ime, Perëndia im, dhe tek ai do të shpresoj."},{"t":"p","x":"Se ai do të të çlirojë prej kurthit të gjahtarëve edhe prej fjalëve turbulluese."},{"t":"p","x":"Do të të mbulojë me pendët e tij, edhe nën krahët e tij do të shpresosh, e vërteta e tij do të të rrethojë si armë e fortë."},{"t":"p","x":"Nuk do të frikësohesh prej tmerrit të natës, as prej shigjetës që fluturon ditën, as prej gjësë që ecën në errësirë, as prej ndonjë gjëje të papritur dhe demonit të mesditës."},{"t":"p","x":"Një mijë do të bien në të majtën tënde dhe dhjetë mijë në të djathtën tënde."},{"t":"p","x":"Por tek ti nuk do të afrohet."},{"t":"p","x":"Për më tepër, me sytë e tu do ta shikosh edhe do ta vështrosh shpagimin e mëkatarëve."},{"t":"p","x":"Sepse ti, o Zot, je shpresa ime, e bëre të Lartin strehën tënde."},{"t":"p","x":"Nuk do të vijë tek ti ndonjë e keqe dhe as ndonjë fatkeqësi nuk do të afrohet në tendën tënde."},{"t":"p","x":"Se do të urdhërojë engjëjt e tij për ty, që të të ruajnë në gjithë udhët e tua."},{"t":"p","x":"Me duar do të të ngrenë, se mos përplasësh këmbën tënde mbi gur."},{"t":"p","x":"Do të shkelësh mbi nepërkë e mbi basilisk dhe do të shtypësh me këmbë luanin dhe dragoin."},{"t":"p","x":"Se shpresoi tek unë dhe do ta çliroj, do ta mbroj atë se njohu emrin tim."},{"t":"p","x":"Do të më thërresë edhe do ta dëgjoj, në shtrëngim do të jem bashkë me të, do ta çliroj edhe do ta lavdëroj atë."},{"t":"p","x":"Me ditë të gjata do ta nginj, edhe do t'i dëftej atij shpëtimin tim."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Aliluia, Aliluia, Aliluia. Lavdi më Ty, o Perëndi. (3 herë)"},{"t":"p","x":"Mëshiro, o Zot (3 herë)."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"rubric","x":"Pastaj psalen Vargjet pasuese në T. T. II duke shtuar në fund si refren:"},{"t":"p","x":"“Se Zoti është bashkë me ne”."},{"t":"p","x":"Zoti është bashkë me ne. Dijeni o kombe që jeni të mundur.","score":"zoti"},{"t":"p","x":"Dëgjojeni anembanë dheut."},{"t":"p","x":"O të fortë do të mundeni."},{"t":"p","x":"Sado të forcoheni, prapë jeni të mundur."},{"t":"p","x":"Zoti do t’i shkatërrojë këshillat tuaja."},{"t":"p","x":"Fjala që do të lidhni, nuk do të qëndrojë."},{"t":"p","x":"Nuk trembemi as tronditemi nga ju."},{"t":"p","x":"Do të bekojmë Zotin, Perëndinë tonë dhe do t’ia kemi frikën."},{"t":"p","x":"Do t’i kemi besim, se ai na shenjtëron."},{"t":"p","x":"Do t’i kemi besim, se ai na shpëton."},{"t":"p","x":"Ja unë dhe djemtë që më dha Perëndia."},{"t":"p","x":"Populli që bariste në errësirë, pa një dritë të madhe."},{"t":"p","x":"Ju rrini nën hijen e vdekjes, po drita shkëlqen përmbi ne."},{"t":"p","x":"Se një djalë na lindi dhe një Bir na u dha."},{"t":"p","x":"Dhe ai do të marrë qeverisjen përsipër."},{"t":"p","x":"Edhe paqja e tij nuk do të ketë kufi."},{"t":"p","x":"Edhe do të quhet emri i tij “Engjëll i Këshillës së Madhe”."},{"t":"p","x":"Këshilltar i çuditshëm."},{"t":"p","x":"Perëndia i fuqishëm, Kryetar, Princ i Paqes."},{"t":"p","x":"Ati i jetës së pritme."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë."},{"t":"p","x":"Tani e përherë e në jetë të jetëve. Amin"},{"t":"p","x":"Zoti është bashkë me ne.","score":"zoti"},{"t":"p","x":"Dijeni o kombe që jini të mundur. Se Zoti është bashkë me ne."},{"t":"rubric","x":"Pastaj lexojmë këto: Si shkova ditën, të përhimnoj O Zot; të lutem falmë mbrëmjen dhe natën të pamëkatshme, o Shpëtimtar dhe shpëtomë. Lavdi Atit e Birit edhe Shpirtit të Shenjtë."},{"t":"p","x":"Si shkova ditën, të lavdëroj o Zot; të lutem falmë mbrëmjen dhe natën pa skandal, o Shpëtimtar dhe shpëtomë."},{"t":"p","x":"Tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Si shkova ditën, të përhimnoj o i Shenjtë; të lutem falmë mbrëmjen dhe natën pa lakmin, o Shpëtimtar dhe shpëtomë."},{"t":"rubric","x":"Pastaj psalin në T.T.II"},{"t":"p","x":"Me trumbeta kipre çdo Kerubim, të këndon plot me bujë dhe lavdërim.","score":"kerubim"},{"t":"p","x":"Dhe me gjashtë krahë çdo Serafim, të himnon pa pushuar me ngazëllim."},{"t":"p","x":"Engjëjt në qiellin shekullor, t’adhurojnë me Psalm edhe Trishenjtor."},{"t":"p","x":"Ishe që prej jetësh o Atë e je, Bir të vetëm pa nisje Jisuin ke."},{"t":"p","x":"Shpirt’i Shenjtë ka gjithatë lavdi, të pandarë të Tre bëjnë një Trini."},{"t":"p","x":"Zonja Virgjëreshë o Shën Mari, lindi Krishtin njeri edhe Perëndi."},{"t":"p","x":"Profetë dhe Dëshmorë plot me lavdi, që fituat parajsë dhe lumturi."},{"t":"p","x":"Bëni ndërmjetime për çdo besnik, të shpëtojmë nga djalli dhe Ferr’i lig."},{"t":"p","x":"Ja ku po ju lutemi pa pushim, Trishenjtorin këndojmë me lavdërim."},{"t":"p","x":"Shenjt, Shenjt, Shenjt, o Zot Trishenjtor, mëshirona dhe shpëtona. Amin."},{"t":"h","x":"Simboli I Besimit"},{"t":"p","x":"Besoj në një Perëndi, Atë të tërëfuqishëm, krijues të qiellit dhe të dheut dhe të gjithë të dukurave dhe të padukurave."},{"t":"p","x":"Dhe në një Zot , Jisu Krishtin, Birin e Perëndisë, të vetëmlindurin, që lindi prej Atit përpara gjithë shekujve. Dritë prej drite, Perëndi të vërtetë prej Perëndie të vërtetë, të lindur, jo të bërë, që ka të qenët një me Atin, me anën e të cilit u bënë të gjitha."},{"t":"p","x":"Që për ne njerëzit edhe për shpëtimin tonë, zbriti prej qiejve, edhe u trupëzua prej Shpirtit të Shenjtë dhe Virgjëreshës Mari dhe u bë njeri."},{"t":"p","x":"Dhe u kryqëzua për ne në kohën e Pontit Pilat , dhe pësoi e u varros."},{"t":"p","x":"Dhe u ngjall të tretën ditë sipas shkrimeve."},{"t":"p","x":"Dhe u ngjit në qiejt dhe rri në të djathtë të Atit."},{"t":"p","x":"Dhe do të vijë përsëri me lavdi të gjykojë të gjallët dhe të vdekurit, mbretëria e të cilit nuk do të ketë mbarim."},{"t":"p","x":"Dhe në Shpirtin e Shenjtë, Zot, jetëbërës, që buron prej Atit, që adhurohet e lavdërohet bashkë me Atin e me Birin, që foli me anën e profetëve."},{"t":"p","x":"Në një Kishë të shenjtë, katholike dhe apostolike."},{"t":"p","x":"Pohoj një pagëzim për ndjesën e mëkateve."},{"t":"p","x":"Pres ngjalljen e të vdekurve."},{"t":"p","x":"Dhe jetën e ardhshme të amëshuar. Amin."},{"t":"rubric","x":"Pastaj psalim në T.T.II"},{"t":"p","x":"Zonjë Hyjlindëse e Tërëshenjtë, ndërmjeto për ne dhe çdo mëkatar. (2 herë)","score":"zonje"},{"t":"p","x":"Engjëj dhe Kryeengjëj të Shenjtë, ndërmjetoni për ne dhe çdo mëkatar."},{"t":"p","x":"(2 herë)"},{"t":"p","x":"Shën Joan Profet, Pararendës, Pagëzor i Zotit tonë Jisu Krisht, ndërmjeto për ne dhe çdo mëkatar. (2 herë)"},{"t":"p","x":"Apostuj dhe Profetë, Dëshmorë dhe Shenjtorë, ndërmjetoni për ne dhe çdo mëkatar. (2 herë)"},{"t":"p","x":"Etër Oshënarë, Barinj edhe Mësues, ndërmjetoni për ne dhe çdo mëkatar. (2 herë)"},{"t":"p","x":"O fuqi e pamundur e Kryqit të çmuar, mos na braktis ne dhe çdo mëkatar. (2 herë)"},{"t":"p","x":"O Perëndi ki mëshirë për ne dhe çdo mëkatar. (3 herë)"},{"t":"p","x":"Dhe mëshirona."},{"t":"h","x":"Trishenjti"},{"t":"p","x":"Shenjt Perëndi, Shenjt i fuqishëm, Shenjt i pavdekshëm, mëshirona. (tri herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Trini e Tërëshenjtë, mëshirona; o Zot, falna mëkatet tona; o Zot i madh, ndjei paudhësitë tona; o i Shenjtë, vështro dhe shëro sëmundjet tona për emrin tënd."},{"t":"p","x":"Mëshiro, o Zot (tri herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Ati ynë që je në qiejt, u shenjtëroftë emri yt, ardhtë mbretëria jote, u bëftë dëshira jote, si në qiell ashtu edhe mbi dhe. Bukën tonë të përditshme jepna neve sot; dhe falna fajet tona, sikurse edhe ne ua falim fajtorëve tanë; dhe mos na shtjer në ngasje, po shpëtona nga i ligu."},{"t":"rubric","x":"Kur bie e Kremte, psalen troparet e së Kremtes."},{"t":"rubric","x":"Të Hënën, të Mërkurën dhe të Premten psalim këto në T.II:"},{"t":"p","x":"Ndritmi sytë, o Krisht Perëndi, që të mos fle gjumin e vdekjes, që të mos thotë armiku, që është më i fortë se unë."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë."},{"t":"p","x":"Forcoma shpirtin o Perëndi, se shkoj nëpër shumë gracka; ruajmë prej atyre si i mirë dhe shpëtomë si njeridashës."},{"t":"p","x":"Tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Meqënëse s'guxojmë nga mëkatet e shumta, ndërmjeto për ne pranë Birit tënd, o Virgjëreshë Hyjlindëse, se lutja e Nënës ka fuqi të madhe pranë Zotit. Mos i përbuz mëkatarët o e mirë, se Zoti është mëshirëplot edhe do të na shpëtojë, se dënjoj të pësojë për ne."},{"t":"p","x":"Mëshiro, o Zot. (40 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Më të nderuarën se Kerubimet dhe më të lavdëruarën pa krahasim se Serafimet, që pa u cënuar linde Fjalën Perëndi, me të vërtetë Hyjlindëse, ty të madhërojmë."},{"t":"p","x":"Me uratat e etërve tanë të shenjtë, O Zot Jisu Krisht Perëndi, mëshirona dhe shpëtona. Amin."},{"t":"p","x":"Ejani t’i falemi e t’i biem ndër këmbë Perëndisë, Mbretit tonë."},{"t":"p","x":"Ejani t’i falemi e t’i biem ndër këmbë Krishtit, Perëndisë, Mbretit tonë."},{"t":"p","x":"Ejani t’i falemi e t’i biem ndër këmbë vetë Krishtit, Perëndisë dhe Mbretit tonë."},{"t":"h","x":"Psalmi 50"},{"t":"p","x":"Përdëllemë, o Perëndi, sipas përdëllimit tënd të madh dhe sipas dhembshurive të tua të shumta shuaje paudhësinë time."},{"t":"p","x":"Lamë krejt prej paudhësisë sime dhe pastromë prej mëkatit tim."},{"t":"p","x":"Se unë e njoh paudhësinë time dhe mëkati im është përpara meje kurdoherë."},{"t":"p","x":"Te ti vetëm mëkatova dhe të keqen e bëra përpara teje, kështu që ti je i drejtë në fjalët e tua dhe i kthjellët në gjykimin tënd."},{"t":"p","x":"Se ja tek u zura në paudhësi, dhe në mëkate më lindi nëna ime."},{"t":"p","x":"Se ja tek deshe të vërtetën, të patreguarat dhe të fshehtat e urtësisë sate m’i tregove."},{"t":"p","x":"Spërkatmë me hisop, dhe do të pastrohem, lajmë dhe do të bëhem më i bardhë se dëbora."},{"t":"p","x":"Bëmë të dëgjoj gëzim e ngazëllim, dhe do të më gëzohen eshtrat e dobësuara."},{"t":"p","x":"Ktheje fytyrën tënde nga mëkatet e mi, dhe shuaji gjithë paudhësitë e mia."},{"t":"p","x":"Krijo zemër të pastër tek unë, o Perëndi, dhe përtërit frymë të drejtë në thellësitë e zemrës sime."},{"t":"p","x":"Mos më hidh larg fytyrës sate, dhe mos e hiq prej meje Shpirtin tënd të Shenjtë."},{"t":"p","x":"Jepma prapë ngazëllimin e shpëtimit tënd dhe forcomë me frymë sunduese."},{"t":"p","x":"Do t’u mësoj të paligjve udhët e tua, dhe të pabesët do të kthehen tek Ti."},{"t":"p","x":"Shpëtomë prej gjakrash, o Perëndi, Perëndia i shpëtimit tim, gjuha ime do të lavdërojë me gëzim drejtësinë tënde."},{"t":"p","x":"O Zot, çel buzët e mia, dhe goja ime do të lëçitë lavdinë tënde."},{"t":"p","x":"Se po të kishe dashur therore do të kisha prurë, por Ty s’të pëlqejnë therore me djegie të plotë."},{"t":"p","x":"Therore ndaj Perëndisë është shpirti i dërrmuar; zemrën e dërrmuar dhe të përulur Perëndia nuk do ta përbuzë."},{"t":"p","x":"Bëji të mirë, o Zot, Sionit, sipas mirëdashjes sate; dhe le të ndërtohen muret e Jerusalemit."},{"t":"p","x":"Atëherë do të të pëlqejë therore drejtësie, dhurata dhe therore me djegie të plotë."},{"t":"p","x":"Atëherë do të sjellin viçër mbi altarin tënd."},{"t":"h","x":"Psalmi 101"},{"t":"p","x":"O Zot, dëgjoje lutjen time, edhe thirrja ime ardhtë tek ti."},{"t":"p","x":"Mos e kthe fytyrën tënde prej meje; në ditën e hidhërimit tim, ule veshin tënd tek unë; atë ditë që do të të thërres, dëgjomë shpejt."},{"t":"p","x":"Se ditët e mia u davaritën porsi tymi edhe eshtrat e mia u thanë porsi bukë e thatë."},{"t":"p","x":"Zemra m'u plagos dhe u tha si bari, sepse harroja të haja bukën time."},{"t":"rubric","x":"Prej zërit të rënkimit tim eshtrat e mia m'u ngjitën në mish."},{"t":"p","x":"U bëra si pelikani i shkretëtirës, u bëra si kukuvajka mbi rrënoja."},{"t":"p","x":"Qëndrova zgjuar dhe u bëra si harabeli që rri i vetmuar mbi çati."},{"t":"p","x":"Tërë ditën më poshtëronin armiqtë e mi, dhe ata që më lavdëronin, u betuan kundër meje."},{"t":"p","x":"Se hëngra hirin porsi bukë edhe me lot përzieva pijen time."},{"t":"p","x":"Për shkak të zemërimit tënd dhe të mërisë sate, se më ngrite dhe më pas më rrëzove."},{"t":"p","x":"Ditët e mia shkuan si hije, edhe unë u thava si bari."},{"t":"p","x":"Po ti, o Zot, mbetesh për gjithë jetën, edhe kujtimi yt brez pas brezi."},{"t":"p","x":"Ti do të ngrihesh që të përdëllesh Sionin, se është koha ta përdëllesh, se i erdhi koha."},{"t":"p","x":"Se shërbëtorëve të tu u pëlqenin gurët e tij, edhe iu dhimbset dheu i tij."},{"t":"p","x":"Dhe kombet do ta kenë frikë emrin tënd, o Zot, edhe të gjithë mbretërit e dheut lavdinë tënde."},{"t":"p","x":"Se Zoti do të ndërtojë Sionin dhe do të shfaqet në lavdinë e tij."},{"t":"p","x":"Hodhi sytë mbi lutjen e të përulurve, edhe nuk e përbuzi përgjërimin e tyre."},{"t":"p","x":"Kjo le të shkruhet për brezin që vjen dhe populli që do të krijohet do të lavdërojë Zotin."},{"t":"p","x":"Se u përkul nga lartësia e shenjtërores së tij, prej qiellit Zoti hodhi sytë mbi dhé."},{"t":"p","x":"Që të dëgjojë psherëtimën e të munduarve, që të çlirojë bijtë e atyre që janë të dënuar me vdekje."},{"t":"p","x":"Që të dëftehet emri i Zotit në Sion, edhe lavdërimi i tij në Jerusalem."},{"t":"p","x":"Kur të mblidhet populli aty dhe mbretërit së bashku për t'i shërbyer Zotit."},{"t":"p","x":"Iu përgjigj atij në rrugën e fuqisë së tij: rrëfemë ditët e pakta që më kanë mbetur."},{"t":"p","x":"Mos më merr në gjysmë të ditëve të mia; vitet e tua janë brez pas brezi."},{"t":"p","x":"Ti, o Zot, që në krye të herës themelove dheun, edhe punë të duarve të tua janë qiejt."},{"t":"p","x":"Ata do të shkatërrohen, por ti do të jesh; të gjithë ata, porsi rrobë, do të vjetrohen, por ti do t'i mbështjellësh ata si me tunikë dhe do të ndryshojnë; Po ti je përherë i njëjti, edhe vitet e tua nuk do të kenë fund."},{"t":"p","x":"Bijtë e shërbëtorëve të tu do të të kenë strehë edhe fara e tyre do të ketë mbarësi përjetë."},{"t":"h","x":"Trishenjti"},{"t":"p","x":"Shenjt Perëndi, Shenjt i fuqishëm, Shenjt i pavdekshëm, mëshirona. (3 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Trini e Tërëshenjtë, mëshirona; o Zot, falna mëkatet tona; o Zot i madh, ndjei paudhësitë tona; o i Shenjtë, vështro dhe shëro sëmundjet tona për emrin tënd."},{"t":"p","x":"Mëshiro, o Zot (3 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Ati ynë që je në qiejt, u shenjtëroftë emri yt, ardhtë mbretëria jote, u bëftë dëshira jote, si në qiell ashtu edhe mbi dhe. Bukën tonë të përditshme jepna neve sot; dhe falna fajet tona, sikurse edhe ne ua falim fajtorëve tanë; dhe mos na shtjer në ngasje, po shpëtona nga i ligu."},{"t":"rubric","x":"Pastaj psalen troparet në T.T.II:"},{"t":"p","x":"Mëshirona, o Zot mëshirona, se duke na munguar çdo mbrojtje, ne mëkatarët të drejtojmë ty, si Zot që je, këtë lutje, mëshirona."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë."},{"t":"p","x":"Mëshirona, o Zot, se te Ti e kemi shpresën, mos u zemëro tepër me ne, as mos i kujto paudhësitë tona, po hidh sytë dhe tani si zemërdhembshur dhe shpëtona nga armiqtë tanë, se Ti je Perëndia ynë dhe ne populli yt, të gjithë jemi vepra të duarve të tua dhe thërresim emrin tënd."},{"t":"p","x":"Tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Hapna derën e dhembshurisë, o Hyjlindëse e bekuar; ne që kemi shpresë tek ti, të mos gabohemi, shpëtofshim me anën tënde nga rastet e këqia, se ti je shpëtim i të krishterëve."},{"t":"p","x":"Mëshiro, o Zot. (40 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Më të nderuarën se Kerubimet dhe më të lavdëruarën pa krahasim se Serafimet, që pa u cënuar linde Fjalën Perëndi, me të vërtetë Hyjlindëse, ty të madhërojmë."},{"t":"p","x":"Me uratat e etërve tanë të shenjtë, O Zot Jisu Krisht Perëndi, mëshirona dhe shpëtona. Amin."},{"t":"p","x":"Ejani t’i falemi e t’i biem ndër këmbë Perëndisë, Mbretit tonë."},{"t":"p","x":"Ejani t’i falemi e t’i biem ndër këmbë Krishtit, Perëndisë, Mbretit tonë."},{"t":"p","x":"Ejani t’i falemi e t’i biem ndër këmbë vetë Krishtit, Perëndisë dhe Mbretit tonë."},{"t":"h","x":"Psalmi 69"},{"t":"p","x":"O Perëndi, ndihmës sime vëri re; o Zot, nxito të më ndihmosh."},{"t":"p","x":"U çnderofshin dhe u turpërofshin ata që kërkojnë shpirtin tim; u kthefshin prapa dhe u turpërofshin ata që duan të këqija kundër meje."},{"t":"p","x":"U kthefshin menjëherë prapa të turpëruar ata që më thonë: Sa mirë, sa mirë!"},{"t":"p","x":"U gëzofshin dhe u dëfrefshin në ty të gjithë ata që të kërkojnë, o Perëndi, edhe ata që duan shpëtimin tënd thënçin përgjithnjë: Zoti qoftë i madhëruar!"},{"t":"p","x":"Po unë jam i varfër dhe nevojtar, o Perëndi, ndihmomë."},{"t":"p","x":"Ti je ndihmësi dhe shpëtimtari im; o Zot, eja shpejt, mos u vono."},{"t":"h","x":"Psalmi 142"},{"t":"p","x":"O Zot, dëgjo faljen time, vëri veshin lutjes sime sipas së vërtetës sate, dëgjomë sipas drejtësisë sate."},{"t":"p","x":"Dhe mos hyr në gjyq me shërbëtorin tënd, se asnjë i gjallë nuk do të dalë i drejtë përpara teje."},{"t":"p","x":"Se armiku ma ndoqi shpirtin tim dhe ma rrëzoi jetën përdhe."},{"t":"p","x":"Më vuri në vende të errëta, si të vdekurit prej kohësh, shpirti m'u trishtua dhe zemra m'u trondit."},{"t":"p","x":"Kujtova ditët e lashta, mendova gjithë veprat e tua, sillja ndër mend punët e duarve të tua."},{"t":"p","x":"I shtriva duart drejt teje, shpirti im ka etje për ty si toka e thatë."},{"t":"p","x":"Dëgjomë shpejt, o Zot, m'u zu fryma, mos e kthe mënjanë fytyrën tënde prej meje, që të mos bëhem si ata që zbresin në varr."},{"t":"p","x":"Bëj që të dëgjoj përdëllimin tënd në mëngjes, se tek ti shpresova."},{"t":"p","x":"Tregomë, o Zot, udhën ku duhet të eci, se tek ti e kam varur shpirtin tim."},{"t":"p","x":"Shpëtomë prej armiqve të mi, o Zot, se tek ti kërkova strehë."},{"t":"p","x":"Mësomë të bëj dëshirën tënde, se ti je Perëndia im."},{"t":"p","x":"Fryma jote e mirë do të më udhëheqë në vend të drejtë."},{"t":"p","x":"Për emrin tënd, o Zot, jepmë jetë."},{"t":"p","x":"Sipas drejtësisë sate, nxirre shpirtin tim nga trishtimi dhe, sipas mëshirës sate, shfarosi armiqtë e mi, dhe shkatërroji të gjithë ata që hidhërojnë shpirtin tim, se unë jam shërbëtori yt."},{"t":"p","x":"Dhoksologjia e vogël"},{"t":"p","x":"Lavdi Perëndisë që është në më të lartat dhe mbi dhenë paqe, dhe mbi njerëzit mirëdashje."},{"t":"p","x":"Të himnojmë, të bekojmë, të falemi, të lavdërojmë, Ty të falenderojmë për lavdinë tënde të madhe."},{"t":"p","x":"Zot mbret, Perëndi qiellor, Atë i tërëfuqishëm; Zot Bir i vetëmlindur Jisu Krisht, edhe Shpirti i Shenjtë."},{"t":"p","x":"Zot Perëndi, qengj i Perëndisë, Bir i Atit që ngre mëkatin e botës, mëshirona, Ti që ngre mëkatet e botës."},{"t":"p","x":"Prano lutjen tonë, Ti që rri në të djathtë të Atit, edhe mëshirona."},{"t":"p","x":"Se Ti je Shenjt i vetëm, Ti je Zot i vetëm, Jisu Krishti, për lavdi të Perëndisë Atit. Amin."},{"t":"p","x":"Për natë do të të bekoj, dhe do të lavdëroj emrin tënd për jetë, e në jetë të jetës."},{"t":"p","x":"O Zot u bëre streha jonë brez pas brezi, unë thashë: O Zot, mëshiromë, shëro shpirtin tim se fajtova tek Ti."},{"t":"p","x":"O Zot, tek Ti gjeta strehë, mësomë të bëj dëshirën tënde se Ti je Perëndia im."},{"t":"p","x":"Se pranë teje është burimi i jetës; me dritën tënde do të shohim dritë."},{"t":"p","x":"Zgjate përdëllimin tënd mbi ata që të njohin."},{"t":"p","x":"Bëna të denjë, o Zot, që të ruhemi këtë natë pa ndonjë mëkat."},{"t":"p","x":"I bekuar je, o Zot, Perëndi i Etërve tanë, dhe emri yt është i himnuar dhe i lavdëruar në jetët. Amin"},{"t":"p","x":"Le të jetë, o Zot, përdëllimi yt mbi ne, sikurse kemi shpresuar tek Ti."},{"t":"p","x":"I bekuar je, o Zot, mësomë porositë e tua."},{"t":"p","x":"I bekuar je, o Kryezot, bëmë të mençëm në porositë e tua."},{"t":"p","x":"I bekuar je, o i Shenjtë, ndriçomë me porositë e tua."},{"t":"p","x":"O Zot, mëshira jote është përjetë, mos i hiq sytë nga veprat e duarve të Tua."},{"t":"p","x":"Ty të ka hije lavdërimi, Ty të ka hije himni, Ty të ka hije lavdia, Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"h","x":"Trishenjti"},{"t":"p","x":"Shenjt Perëndi, Shenjt i fuqishëm, Shenjt i pavdekshëm, mëshirona. (3 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Trini e Tërëshenjtë, mëshirona; o Zot, falna mëkatet tona; o Zot i madh, ndjei paudhësitë tona; o i Shenjtë, vështro dhe shëro sëmundjet tona për emrin tënd."},{"t":"p","x":"Mëshiro, o Zot (3 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Ati ynë që je në qiejt, u shenjtëroftë emri yt, ardhtë mbretëria jote, u bëftë dëshira jote, si në qiell ashtu edhe mbi dhe. Bukën tonë të përditëshme jepna neve sot; dhe falna fajet tona, sikurse edhe ne ua falim fajtorëve tanë; dhe mos na shtjer në ngasje, po shpëtona nga i ligu."},{"t":"p","x":"Kirie ton dhinameon në T.T.II ose T.T.IV","score":"fuqi"},{"t":"p","x":"Zot i madh i fuqive, eja tok me ne, ndihmës tjetër s'kemi, në shtrëngim të zemrave të thyera. Zot i madh i fuqive, mëshirë ki për ne."},{"t":"p","x":"Lavdërojeni Perëndinë në shenjtoren e Tij, lavdërojeni atë në vendin e shkëlqimit të fuqisë së Tij."},{"t":"p","x":"Zot i madh..."},{"t":"p","x":"Lavdërojeni për fuqitë e Tij; lavdërojeni sipas madhërisë së Tij të shumtë."},{"t":"p","x":"Zot i madh..."},{"t":"p","x":"Lavdërojeni me zë trumbete; lavdërojeni me harpë dhe me kitarë."},{"t":"p","x":"Zot i madh..."},{"t":"p","x":"Lavdërojeni me timpan dhe valle; lavdërojeni me korda dhe instrumente."},{"t":"p","x":"Zot i madh..."},{"t":"p","x":"Lavdërojeni me çimbale tingëlluese, lavdërojeni me çimbale brohoritjeje. Çdo frymë le të lavdërojë Zotin."},{"t":"p","x":"Zot i madh..."},{"t":"p","x":"Lavdërojeni Perëndinë në shenjtoren e Tij."},{"t":"p","x":"Zot i madh..."},{"t":"p","x":"Lavdërojeni atë në vendin e shkëlqimit të fuqisë së Tij."},{"t":"p","x":"Zot i madh i fuqive, eja tok me ne, ndihmës tjetër s'kemi, në shtrëngim të zemrave të thyera. Zot i madh i fuqive, mëshirë ki për ne."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë."},{"t":"p","x":"Sikur të mos kishin ndërmjetarë, Shenjtorët pranë teje o Zot, si do të guxonim të të himnonim ty, o Shpëtimtar që të bekojnë Engjëjt pa pushuar: Kursenaji shpirtrat, o zemërnjohës."},{"t":"p","x":"Tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Kam shumë faje o Hyjlindëse, dhe përiki pranë teje, dhe të lutem shpëtomë. Vizitoma shpirtin e sëmurë dhe ndërmjeto pranë Birit tënd, të më falë ndjesën e mëkateve, o e vetmja e bekuar."},{"t":"rubric","x":"Dhe pastaj psalim në T.II:"},{"t":"p","x":"Hyjlindëse e tërëshenjtë, mos më braktis për tërë jetën; mos më ler në mbrojtje njerëzore, po ti vetë përkrahmë dhe mëshiromë.","score":"braktis"},{"t":"p","x":"Gjithë shpresën time tek ty e vë o Nënë e Perëndisë, ruajmë në mbrojtjen tënde."},{"t":"p","x":"Mëshiro, o Zot. (40 herë)"},{"t":"p","x":"O Krisht, Perëndi që adhurohesh e lavdërohesh në çdo kohë e në çdo orë në qiell e mbi dhe, zemërgjerë, zemërdhembshur, mëshirëplotë, që do të drejtët dhe mëshiron mëkatarët, që i thërret të gjithë në shpëtim me zotimin e të mirave të pritme, ti o Zot, prit lutjet tona në këtë orë dhe drejto jetesën tonë sipas porosive të tua. Shenjtërona shpirtrat, pastrona trupat, ndreqna mendimet, pastrona mendjet dhe shpëtona prej çdo hidhërimi, të keqeje dhe helmi. Mbrona me ëngjëjt e tu të shenjtë që duke u ruajtur dhe duke u udhëhequr prej ushtrisë së tyre të arrijmë të baresim te bashkimi i fesë dhe te njohja e lavdisë sate të paafruar, se i bekuar je në jetë të jetëve. Amin."},{"t":"p","x":"Mëshiro, o Zot. (tri herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Më të nderuarën se Kerubimet dhe më të lavdëruarën pa krahasim se Serafimet, që pa u cënuar linde Fjalën Perëndi, me të vërtetë Hyjlindëse, ty të madhërojmë."},{"t":"rubric","x":"Pastaj bëjmë tri metani duke thënë lutjen e mëposhtme:"},{"t":"h","x":"Lutja E Oshënar Efremit"},{"t":"p","x":"Zot dhe Mjeshtër i jetës sime, mos më jep frymë përtese, kureshtje, lavdidashjeje dhe kotësie."},{"t":"p","x":"Po falmë frymë urtësie, përulësie, durimi dhe dashurie."},{"t":"p","x":"Vlerësomë, o Zot dhe Mbret, t’i shikoj fajet e mia dhe të mos e gjykoj tim vëlla."},{"t":"rubric","x":"Pastaj bëjmë dymbëdhjetë metani të vogla dhe në fund një të madhe me"},{"t":"p","x":"vargun e tretë:"},{"t":"p","x":"Vlerësomë, o Zot dhe Mbret, t’i shikoj fajet e mia dhe të mos e gjykoj tim vëlla. Se i bekuar je në jetë të jetëve. Amin"},{"t":"h","x":"Trishenjti"},{"t":"p","x":"Shenjt Perëndi, Shenjt i fuqishëm, Shenjt i pavdekshëm, mëshirona. (3 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Trini e Tërëshenjtë, mëshirona; o Zot, falna mëkatet tona; o Zot i madh, ndjei paudhësitë tona; o i Shenjtë, vështro dhe shëro sëmundjet tona për emrin tënd."},{"t":"p","x":"Mëshiro, o Zot (3 herë)"},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë; tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Ati ynë që je në qiejt, u shenjtëroftë emri yt, ardhtë mbretëria jote, u bëftë dëshira jote, si në qiell ashtu edhe mbi dhe. Bukën tonë të përditëshme jepna neve sot; dhe falna fajet tona, sikurse edhe ne ua falim fajtorëve tanë; dhe mos na shtjer në ngasje, po shpëtona nga i ligu."},{"t":"p","x":"Mëshiro o Zot. (12 herë)"},{"t":"p","x":"Dhe shpëtona o Virgjëreshë e Tërëshenjtë"},{"t":"h","x":"Uratë Drejtuar Së Tërëshenjtës Mari"},{"t":"rubric","x":"Prej Pavlit, murgut të Manastirit të Evergjetit"},{"t":"p","x":"E papikëluar, e papërlyer, e pacënuar, e panjollshme, Virgjëreshë e pastër, Zonjë nuse e Perëndisë, që bashkove Fjalën Perëndi me njerëzit me lindjen tënde të çuditshme dhe mbështete natyrën e hedhur të gjendjes sonë më qielloret, e vetmja shpresë e të dëshpëruarve dhe ndihma e të luftuarve, përkrahja e gatshme e atyre që rendin tek ti dhe përikja e gjithë të krishterëve, mos të ardhtë ndot nga unë mëkatari, i fëlliquri që prisha tërë veten time në mendime, fjalë dhe vepra të turpshme dhe që u bëra rob duke dashur prej ngathtësisë së dëfrimeve të jetës, po si nënë e Perëndisë, njeridashëse, le të të vijë keq për mua mëkatarin dhe birin e shthurur dhe prit lutjen që të blatohet prej buzësh të ndyra; dhe lutju Birit tënd dhe Zotit tonë, duke përdorur guximin tënd nënor që të më hapë dhe mua zemrën njeridashëse të mirësisë së tij; dhe duke mos vënë re fajet e mia të panumërta, të më kthejë në pendim dhe të më tregojë punëtor të mbaruar të porosive të tij. Dhe ji pranë meje gjithnjë, si mëshirëplote, bashkëvuajtëse dhe mirëdashëse; në këtë jetë mbrojtëse dhe ndihmëse e nxehtë, duke thyer sulmet e kundërshtarëve dhe duke më udhëhequr tek shpëtimi; dhe në kohë të ikjes sime, duke u kujdesur për shpirtin tim të mjerë dhe duke dëbuar larg faqet e errëta të demonëve të ligj, dhe në ditën e frikshme të gjyqit, shpëtomë nga ferri i përjetshëm dhe tregomë trashëgimtar të lavdisë së fshehtë të Birit tënd dhe Perëndisë tonë, të cilin e paça, o Zonja ime Hyjlindëse e Tërëshenjtë, me ndërmjetimin dhe përkrahjen tënde, me hirin dhe njeridashjen e Birit tënd të vetëmlindur, Zotit dhe Perëndisë dhe Shpëtimtarit tonë Jisu Krisht, i cili meriton çdo lavdi, nder dhe adhurim bashkë me Atin e tij pa fillim dhe Shpirtin e tij të Tërëshenjtë, të mirë dhe jetëbërës, tani e përherë e në jetë të jetëve. Amin."},{"t":"h","x":"Uratë Drejtuar Zotit Tonë Jisu Krisht"},{"t":"rubric","x":"Prej Antiokut, murgut të Pandektit"},{"t":"p","x":"Dhe jepna, o Zot neve që shkojmë për gjumë, prehje trupi dhe shpirti dhe ruajna nga gjumi i errët i mëkatit dhe prej çdo dëshire të errët e të natshme. Pusho hovet e pasioneve, shuaj shigjetat e zjarrta të të ligut që lëvizin kundër nesh dinakërisht, thyej kryengritjet e trupit tonë dhe vër në gjumë çdo mendim tokësor e lëndor. Dhe dhurona, o Perëndi, mendje të vigjëluar, mendim të urtë, zemër esëll, gjumë të lehtë dhe pa ndonjë fantazi satanike. Dhe zgjona në kohë të faljes të mbështetur në porositë e tua dhe duke patur në veten tonë kujtimin e gjykimeve të tua të pakthyera. Falna lavdërimin tënd tërë natën, që të himnojmë, të bekojmë e të lavdërojmë emrin tënd të nderuar e madhështor, të Atit, të Birit dhe të Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"E përmbilavdëruar, gjithmonë Hyjlindëse e kulluar, shpjerja lutjen tonë Birit tënd, dhe lypi të shpëtojë shpirtrat tanë me anën tënde."},{"t":"h","x":"Urata E Shën Joanikut"},{"t":"p","x":"Shpresa ime është Ati, përikja ime është Biri, mbrojtja ime është Shpirti i Shenjtë, Trini e Shenjtë lavdi me ty."},{"t":"p","x":"Gjithë shpresën time tek ty e vë o Nënë e Perëndisë, ruajmë në mbrojtjen tënde."},{"t":"p","x":"Lavdi Atit e Birit edhe Shpirtit të Shenjtë, tani e përherë e në jetë të jetëve. Amin."},{"t":"p","x":"Mëshiro, o Zot. (3 herë)"},{"t":"rubric","x":"Të Hënën dhe të Mërkurën psalim:"},{"t":"h","x":"Oli Apothemeni T.T.Ii"},{"t":"p","x":"Mos më braktis tani, pa mbrojtje o Virgjëreshë, Zonjë dhe Hyjlindëse, eja prite lutjen e shërbëtorit tënd; helmi më përmbyti krejt, nuk i duroj dot më shigjetimet e demonëve, strehë gjëkundi s’gjej, as ku të përiki i varfëri, luftë rreth e rrotull kam, tjetër ngushëllim gjetkë nuk shoh. Zonj’e tërë botës, ti shpresë e mbrojtje je për çdo besnik, mos m’i përbuz pra të luturat, në mëshirë dhe shpëtim."},{"t":"rubric","x":"Të Martën dhe të Enjten psalim:"},{"t":"h","x":"Sfajin Su Tin Adhikon T.I"},{"t":"p","x":"Të therur si qengj o Zoti Krisht, Virgjëresha kur të pa, po të thërriste me vaj e lot. O i përmallshim Bir, si pa faj të varën, të mbërthyen përmbi kryq, që dhen’e vare mbi ujëra. Mos vdis dhe mos më lër, mua Nënën vetëm dhe në zi, të shkretuar, o Zot i mëshirave."},{"t":"role","who":"Prifti","x":"Me uratat e Etërve tanë të shenjtë, o Zot Jisu Krisht Perëndi, mëshirona dhe shpëtona. Amin","pr":1},{"t":"role","who":"Lexuesi","x":"Amin.","pr":1},{"t":"role","who":"Lexuesi","x":"Me uratat e Etërve tanë të shenjtë, o Zot Jisu Krisht, Perëndia ynë, mëshirona dhe shpëtona. Amin.","np":1}]}]}]};
